// DOBRZE (struktura package-by-feature): Repository package-private, dostepne TYLKO w orders/
package com.example.orders;
class OrderRepository { void save(Object order) { /* ... */ } } // bez "public"!

class OrderService { // jedyna klasa w tym pakiecie majaca dostep do OrderRepository
    private final OrderRepository repository = new OrderRepository();
    void placeOrder(Object order) { repository.save(order); }
}
